INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(94035, 'ruRU', 'Килрогг... отомстит за меня...', '', 24330),
(94036, 'ruRU', '|TInterface\\Icons\\Spell_Shadow_ChillTouch.blp:20|t|cFFFF0000|Hspell:182008|h[Скрытая энергия]|h|r оскверняет вас!', '', 24330),
(94037, 'ruRU', '|TInterface\\Icons\\Spell_Shadow_SeedOfDestruction.blp:20|tВаше |cFFFF0000|Hspell:181508|h[Семя разрушения]|h|r испустит |cFFFF0000|Hspell:181498|h[Волны разрушения]|h|r.', '', 24330),
(94038, 'ruRU', '|TInterface\\Icons\\ability_deathwing_grasping_tendrilsgreen.blp:20|t|cFFFF0000|Hspell:179582|h[Грохочущие расселины]|h|r затвердевают в |cFFFF0000|Hspell:179620|h[Кристаллы Скверны]|h|r!', '', 24330),
(94039, 'ruRU', '|TInterface\\Icons\\ability_warlock_moltencoregreen.blp:20|tТопор повелителя Скверны Закууна начинает испускать |cFFFF0000|Hspell:179622|h[Взрывы Скверны]|h|r!', '', 24330),
(94040, 'ruRU', '|TInterface\\Icons\\inv_axe_2h_pvphorde_a_01blackhigh.blp:20|tПовелитель Скверны Закуун снова берёт в руки топор, |cFFFF0000|Hspell:179670|h[Вооружаясь]|h|r.', '', 24330),
(94041, 'ruRU', '|TInterface\\Icons\\inv_axe_2h_orgrimmarraid_d_01.blp:20|tПовелитель Скверны Закуун впадает в неистовство и теперь |cFFFF0000|Hspell:179671|h[Тяжело вооружён]|h|r!', '', 24330),
(94042, 'ruRU', 'Какова твоя воля, Архидруид? Смерть и ужас окружают нас...', '', 24330),
(94043, 'ruRU', '|TInterface\\Icons\\warrior_talent_icon_mastercleaver.blp:20|tТопор повелителя Скверны Закууна испускает |cFFFF0000|Hspell:181498|h[Волны разрушения]|h|r!', '', 24330),
(94044, 'ruRU', 'Наконец-то перерыв от скуки всей этой «подготовки»!', '', 24330),
(94045, 'ruRU', 'Он вернёт меня... он никогда не закончит... с нами...', '', 24330),
(94046, 'ruRU', 'Вы вытаскиваете Пеплосерд из земли и торжествующе поднимаете его. Мгновение спустя перед вами появляется Балназар.', '', 24330),
(94050, 'ruRU', 'Всё потеряно...', '', 24330),
(94051, 'ruRU', 'Не дай им снова скормить меня гончим...', '', 24330),
(94052, 'ruRU', 'Я хорошо сражался при жизни... мне здесь не место', '', 24330),
(94053, 'ruRU', 'Хелира! Услышь мои мольбы! Прошу... освободи меня.', '', 24330),
(94054, 'ruRU', 'Обречены... мы все обречены.', '', 24330),
(94055, 'ruRU', 'Хелира, отправь меня на вечное поле боя. Я достоин!', '', 24330),
(94056, 'ruRU', 'Если мы не поспешим, дол будет захвачен. Друиды, одолжите мне свои когти!', '', 24330),
(94057, 'ruRU', 'Наши потери были почти невыносимы... но мы прошли через это. До этого самого момента!', '', 24330),
(94058, 'ruRU', 'Наша осада началась в тот момент, как ты захватил лодки. Казалось, бой затянется надолго, пока значительная часть их сил внезапно не отступила — вероятно, когда ты атаковал с востока.$b$b\nТогда мы ударили всем, что у нас было. Таэлин привёл мощный осадный таран, и ворота быстро пали. Но тут мы столкнулись с новым врагом... орками Скверны. Они жестоко теснят нас, и мы не можем продвинуться. Надеюсь, на востоке тебе повезло больше.', '', 24330),
(94059, 'ruRU', 'Умри!', '', 24330),
(94060, 'ruRU', 'Тебе не выиграть этот бой!', '', 24330),
(94061, 'ruRU', 'Я искупаюсь в твоей крови!', '', 24330),
(94062, 'ruRU', 'Я вознесусь!', '', 24330),
(94063, 'ruRU', 'Снова встретились, друг. Это не Горгронд, но я не скучаю по гигантским тварям, что сотрясают землю!$b$bУ меня есть сведения о Зет\'Голе, Храме Ша\'наар и Зорамской трясине.', '', 24330),
(94064, 'ruRU', 'Расскажи мне о Зет\'Голе.', '', 24330),
(94065, 'ruRU', 'Хелия, узри мою силу. Я достоин!', '', 24330),
(94066, 'ruRU', 'Эти из Кровавой Пустоши — грозные охотники и звероловы. Они неплохо устроились в этих джунглях. В глубине своей деревни они практикуют тёмную кровавую магию. Это точно не сулит нам ничего хорошего, так что рекомендую сжечь эту деревню дотла при первой же возможности!', '', 24330),
(94068, 'ruRU', 'Что происходит в Храме Ша\'наар?', '', 24330),
(94069, 'ruRU', 'Они разрушили эту деревню некоторое время назад и устроили на её месте тренировочные площадки, призыв демонов и превращение живой природы в оружие Скверны.$b$bЛюди, погибшие здесь, должны быть отомщены, командир!', '', 24330);
